const { GoogleGenAI } = require("@google/genai");
const { execSync } = require("child_process");
const fs = require("fs");

const API_KEY = process.env.API_KEY;
const GITHUB_REF = process.env.GITHUB_REF || ""; // refs/tags/v1.0.0

if (!API_KEY) {
  console.error("Error: GEMINI_API_KEY is missing.");
  process.exit(1);
}

// 1. Determine Tag Range
const currentTag = GITHUB_REF.replace("refs/tags/", "");
let previousTag = "";

try {
  // Get the tag before the current one
  previousTag = execSync(`git describe --tags --abbrev=0 ${currentTag}^ 2>/dev/null`)
    .toString()
    .trim();
} catch (e) {
  console.log("No previous tag found. Using initial commit.");
  // Fallback if this is the first tag
  previousTag = execSync("git rev-list --max-parents=0 HEAD").toString().trim();
}

console.log(`Generating notes for ${currentTag} (since ${previousTag})...`);

// 2. Get Merged PRs using git log
// We use git log to find merge commits between tags.
// Format: hash|subject|body
const logOutput = execSync(
  `git log ${previousTag}..${currentTag} --merges --pretty=format:"%h|%s|%b" --separator="END_COMMIT"`
).toString();

const merges = logOutput.split("END_COMMIT").filter((s) => s.trim()).map((entry) => {
  const [hash, subject, body] = entry.split("|");
  return {
    hash: hash ? hash.trim() : "",
    subject: subject ? subject.trim() : "",
    body: body ? body.trim() : "",
  };
});

if (merges.length === 0) {
  console.log("No merged PRs found in this range.");
  fs.writeFileSync("release_notes.md", "No significant changes found.");
  process.exit(0);
}

// 3. Call Gemini
const client = new GoogleGenAI({ apiKey: API_KEY });

const prompt = `
  You are a Release Manager.
  I have a list of merge commits for version ${currentTag}.

  Goal: Generate professional Release Notes.

  1. Categorize changes into 'Features', 'Bug Fixes', and 'Maintenance'.
  2. Use the merge subject and body to infer the context.
  3. Output ONLY valid Markdown.

  Merge Commits:
  ${JSON.stringify(merges)}
`;

async function run() {
  try {
    const response = await client.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
    });

    const markdown = response.text || "Release notes generation failed.";

    // Append auto-generated footer
    const finalOutput = `${markdown}\n\n*Generated by Gemini Release Agent*`;

    fs.writeFileSync("release_notes.md", finalOutput);
    console.log("✅ release_notes.md created successfully.");
  } catch (error) {
    console.error("Gemini API Error:", error);
    process.exit(1);
  }
}

run();
